<script>
  import {onMount,onDestroy} from 'svelte';import {client,createLoader,tablePath,isAbort,date,fmt} from '../lib/api.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';import Secret from '../components/Secret.svelte';import Confirm from '../components/Confirm.svelte';import Select from '../components/Select.svelte';
  export let table;export let lang='vi';const resource=createLoader();let name='',scopes='read',expires='',error='',success='',busy='',secret='',secretName='',timer,confirm=null,alive=true,copied=false;
  $: t=(vi,en)=>lang==='en'?en:vi;
  function load(){return resource.load(signal=>client.request(`${tablePath(table.slug)}/keys`,{signal}));}
  function clearSecret(){secret='';secretName='';copied=false;clearTimeout(timer);}
  function showSecret(value,title){clearSecret();secret=value;secretName=title;timer=setTimeout(clearSecret,30000);}
  async function run(key,fn){if(busy)return;busy=key;error='';success='';try{await client.mutate(`${table.slug}:key:${key}`,fn);}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy='';}}
  function create(){if(!name.trim())return;const body={name:name.trim(),scopes:scopes.split(','),expires_days:expires?Number(expires):null};run('create',async()=>{const result=await client.request(`${tablePath(table.slug)}/keys`,{method:'POST',body});if(alive){showSecret(result.key,result.name);name='';success=result.can_reveal?t('Đã tạo khoá API.','API key created.'):t('Hãy sao chép ngay. Khoá này không có bản lưu để xem lại.','Copy now. This key cannot be revealed later.');load();}});}
  function reveal(key){run(`reveal:${key.id}`,async()=>{const result=await client.request(`${tablePath(table.slug)}/keys/${key.id}/reveal`,{method:'POST'});if(alive)showSecret(result.key,key.name);});}
  function toggle(key){run(`toggle:${key.id}`,async()=>{await client.request(`${tablePath(table.slug)}/keys/${key.id}`,{method:'PATCH',body:{active:!key.active}});if(alive)load();});}
  function remove(key){confirm={title:t('Xoá khoá API','Delete API key'),message:`${t('Khoá sẽ ngừng hoạt động:','This key will stop working:')} ${key.name}`,fn:()=>run(`delete:${key.id}`,async()=>{await client.request(`${tablePath(table.slug)}/keys/${key.id}`,{method:'DELETE'});if(alive){confirm=null;clearSecret();load();}})};}
  async function copy(){try{await navigator.clipboard.writeText(secret);copied=true;}catch{error=t('Không sao chép được. Hãy chọn và sao chép thủ công.','Copy failed. Select and copy the key manually.');}}
  const hide=()=>{if(document.hidden)clearSecret();};
  onMount(()=>{load();document.addEventListener('visibilitychange',hide);window.addEventListener('pagehide',clearSecret);});onDestroy(()=>{alive=false;resource.dispose();clearSecret();document.removeEventListener('visibilitychange',hide);window.removeEventListener('pagehide',clearSecret);});
</script>
<Notice {error} {success} {lang}/>
{#if secret}<section class="panel border-brand/30 mb-5"><div class="flex flex-wrap items-end gap-3"><div class="flex-1 min-w-52"><Secret bind:value={secret} label={`${t('Khoá API','API key')} · ${secretName}`} autocomplete="off" readonly {lang}/></div><Button on:click={copy}><Icon name="copy" size={16}/>{copied?t('Đã sao chép','Copied'):t('Sao chép','Copy')}</Button><Button on:click={clearSecret}>{t('Đóng','Close')}</Button></div><p class="text-xs text-muted mt-3">{t('Tự ẩn sau 30 giây, khi đổi màn hình hoặc rời tab.','Cleared after 30 seconds, navigation or leaving this tab.')}</p></section>{/if}
<section class="panel"><h2 class="mb-5">{t('Tạo khoá API','Create API key')}</h2><form class="grid sm:grid-cols-2 xl:grid-cols-[2fr_1fr_1fr_auto] gap-4 items-end" on:submit|preventDefault={create}><label class="field"><span>{t('Tên khoá','Key name')}</span><input bind:value={name} maxlength="120" required placeholder={t('Ví dụ: chatbot tư vấn','e.g. Support chatbot')}/></label><div class="field"><span>{t('Phạm vi','Scopes')}</span><Select bind:value={scopes} label={t('Phạm vi','Scopes')} options={[{value:'read',label:t('Chỉ đọc','Read only')},{value:'read,write',label:t('Đọc và ghi','Read and write')}]}/></div><label class="field"><span>{t('Hết hạn sau (ngày)','Expires after (days)')}</span><input type="number" min="1" max="3650" bind:value={expires} placeholder={t('Không giới hạn','No expiry')}/></label><Button type="submit" variant="primary" busy={busy==='create'} disabled={!!busy}><Icon name="plus" size={17}/>{t('Tạo khoá','Create key')}</Button></form></section>
<section class="panel mt-5"><div class="flex justify-between items-center mb-5"><h2>{t('Danh sách khoá','API keys')}</h2><Button busy={$resource.loading} on:click={load}><Icon name="refresh" size={16}/>{t('Tải lại','Reload')}</Button></div><Notice error={$resource.error} retry={load} {lang}/><div aria-busy={$resource.loading}>{#if $resource.loading&&!$resource.data}<div class="empty" role="status">{t('Đang tải khoá…','Loading keys…')}</div>{:else if $resource.data?.length}<div class="table-scroll"><table class="data-table"><thead><tr>{#each [t('Tên khoá','Name'),'Prefix',t('Phạm vi','Scopes'),t('Trạng thái','Status'),t('Hết hạn','Expires'),t('Lượt dùng','Uses'),t('Dùng gần nhất','Last used'),t('Thao tác','Actions')] as h}<th>{h}</th>{/each}</tr></thead><tbody>{#each $resource.data as key (key.id)}{@const expired=key.expires_at && new Date(key.expires_at)<new Date()}<tr><td class="font-semibold">{key.name}</td><td><code>{key.prefix}…</code></td><td>{key.scopes.join(', ')}</td><td><span class="badge" class:ok={key.active&&!expired} class:bad={!key.active||expired}>{!key.active?t('Tắt','Disabled'):expired?t('Hết hạn','Expired'):t('Đang bật','Active')}</span></td><td class="whitespace-nowrap">{date(key.expires_at)}</td><td>{fmt(key.use_count)}</td><td class="whitespace-nowrap">{date(key.last_used_at)}</td><td><div class="flex gap-2">{#if key.can_reveal}<Button busy={busy===`reveal:${key.id}`} disabled={!!busy} on:click={()=>reveal(key)}>{t('Xem khoá','Reveal')}</Button>{/if}<Button disabled={!!busy} on:click={()=>toggle(key)}>{key.active?t('Tắt','Disable'):t('Bật','Enable')}</Button><Button variant="ghost" label={`${t('Xoá','Delete')} ${key.name}`} disabled={!!busy} on:click={()=>remove(key)}><Icon name="trash" size={16}/></Button></div></td></tr>{/each}</tbody></table></div>{:else if !$resource.error}<div class="empty"><h2>{t('Chưa có khoá API','No API keys yet')}</h2><p>{t('Tạo khoá để kết nối ứng dụng với bảng này.','Create a key to connect your app to this table.')}</p></div>{/if}</div></section>
{#if confirm}<Confirm {...confirm} {lang} busy={!!busy} onconfirm={confirm.fn} oncancel={()=>confirm=null}/>{/if}
